#include "glintfx/image.hpp"

#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

#include <sys/resource.h>
#include <sys/wait.h>
#include <unistd.h>

#ifndef GLINTFX_PROBE_CORPUS_DIR
#error "GLINTFX_PROBE_CORPUS_DIR must be supplied by tests/CMakeLists.txt (build-time corpus dir)"
#endif

namespace {

int g_failures = 0;

void check(bool cond, const char* what) {
  if (!cond) {
    std::fprintf(stderr, "FAIL: %s\n", what);
    ++g_failures;
  }
}

std::string corpus_path(const char* fixture_name) {
  return std::string(GLINTFX_PROBE_CORPUS_DIR) + "/" + fixture_name;
}

// EN: Reads an entire file into memory, for the general-dispatch (decode_image_memory())
//     leg of Group 1, which takes bytes rather than a path. Returns an empty vector on any
//     I/O failure -- the caller's own check() reports that as a setup failure, distinct from
//     the decode assertions that follow.
// PT: Lê um arquivo inteiro pra memória, pra perna de dispatch geral (decode_image_memory())
//     do Grupo 1, que recebe bytes em vez de um path. Devolve um vector vazio em qualquer
//     falha de I/O -- o próprio check() do chamador reporta isso como falha de setup,
//     distinta das asserções de decode que seguem.
std::vector<unsigned char> read_whole_file(const std::string& path) {
  std::ifstream f(path, std::ios::binary);
  if (!f)
    return {};
  return std::vector<unsigned char>(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());
}

long read_vm_size_bytes() {
  std::ifstream f("/proc/self/status");
  if (!f)
    return -1;
  std::string line;
  while (std::getline(f, line)) {
    if (line.compare(0, 7, "VmSize:") == 0) {
      std::istringstream iss(line.substr(7));
      long kb = -1;
      iss >> kb;
      if (kb < 0)
        return -1;
      return kb * 1024;
    }
  }
  return -1;
}

} // namespace

using namespace glintfx;

int main() {
  // ===========================================================================================
  // EN: Group 1 (DEC-FORMAT-SURFACE, A-2) -- fake_tga_garbage.png, read from the build-time-
  //     generated corpus (see this file's own top comment for why no write happens here).
  // PT: Grupo 1 (DEC-FORMAT-SURFACE, A-2) -- fake_tga_garbage.png, lido do corpus gerado em
  //     build-time (ver o próprio comentário de topo deste arquivo pro porquê de nenhuma
  //     escrita acontecer aqui).
  // ===========================================================================================
  {
    const std::string path = corpus_path("fake_tga_garbage.png");
    const std::vector<unsigned char> bytes = read_whole_file(path);
    check(bytes.size() == 82,
          "Group 1 setup: fake_tga_garbage.png read from the build-time corpus is exactly 82 bytes");

    if (!bytes.empty()) {
      const DecodedImagePixels general = decode_image_memory(bytes.data(), bytes.size());
      check(general.ok,
            "1a: decode_image_memory (general dispatch) STILL accepts the corpus's 82-byte fake "
            "TGA header -- documents the coador this slice does not change on the general entry "
            "point");
      check(general.width == 4096 && general.height == 4096,
            "1a: general dispatch decodes it as 4096x4096 (the consumer's own measured coador shape)");
      check(general.pixels.size() == 4096u * 4096u * 4u,
            "1a: general dispatch allocates the full 67 108 864-byte all-zero-alpha buffer");
    }

    const DecodedImagePixels restricted = decode_png_file(path.c_str());
    check(!restricted.ok,
          "1b: decode_png_file REJECTS the exact fake-TGA-header bytes the build-time corpus "
          "generated (ok == false) -- THE DEC-FORMAT-SURFACE regression this file exists to pin, "
          "using the consumer's OWN generator output, not a hand-transcribed literal");
  }

  // ===========================================================================================
  // EN: Group 2 (DEC-NOTHROW, A-1) -- png_pal_12000.png, the consumer's own 12000x12000
  //     paletted fixture, read directly by path (no scratch copy needed -- it already exists
  //     on disk, produced once at build time). See this file's own top comment for the full
  //     two-stage calibrate-then-squeeze derivation and the measured cost (~1099 MiB
  //     calibration delta, ~1.05 s wall time, ~1.1 GiB peak RSS).
  // PT: Grupo 2 (DEC-NOTHROW, A-1) -- png_pal_12000.png, a própria fixture paletizada
  //     12000x12000 do consumidor, lida diretamente pelo path (nenhuma cópia de scratch
  //     necessária -- já existe em disco, produzida uma vez em build time). Ver o próprio
  //     comentário de topo deste arquivo pra derivação completa de dois estágios
  //     calibrar-depois-apertar e o custo medido (~1099 MiB de delta de calibração, ~1,05 s de
  //     tempo de parede, ~1,1 GiB de RSS de pico).
  // ===========================================================================================
  {
    const std::string path = corpus_path("png_pal_12000.png");

    // -----------------------------------------------------------------------------------------
    // EN: STAGE 1/2 -- CALIBRATE. Unconstrained child decodes the corpus file to completion
    //     (must succeed) and reports back, via a pipe, VmPeak - baseline: the REAL, measured
    //     virtual-address-space growth THIS exact call needed. See image_decode_hardening_
    //     sanity.cpp's own Group B top comment for why this measure-then-squeeze design
    //     replaced an earlier hand-derived fixed multiplier that undershot the real peak.
    // PT: ESTÁGIO 1/2 -- CALIBRAR. Filho não-restringido decodifica o arquivo do corpus até o
    //     fim (precisa ter sucesso) e reporta de volta, via um pipe, VmPeak - baseline: o
    //     crescimento REAL, medido, de espaço de endereço virtual que ESTA chamada exata
    //     precisou. Ver o próprio comentário de topo do Grupo B de image_decode_hardening_
    //     sanity.cpp pro porquê deste desenho medir-depois-apertar substituir um multiplicador
    //     fixo derivado à mão anterior que ficava abaixo do pico real.
    // -----------------------------------------------------------------------------------------
    int cal_pipe[2] = {-1, -1};
    long cal_delta_bytes = -1;
    bool cal_ok = false;
    if (pipe(cal_pipe) == 0) {
      const pid_t cal_pid = fork();
      check(cal_pid >= 0, "Group 2 calibration: fork() succeeded");
      if (cal_pid == 0) {
        close(cal_pipe[0]);
        const long b = read_vm_size_bytes();
        const DecodedImagePixels decoded = decode_image_file(path.c_str()); // unconstrained -- must succeed.
        long peak_kb = -1;
        std::ifstream f2("/proc/self/status");
        std::string line2;
        while (std::getline(f2, line2)) {
          if (line2.compare(0, 7, "VmPeak:") == 0) {
            std::istringstream iss(line2.substr(7));
            iss >> peak_kb;
            break;
          }
        }
        long delta = (b >= 0 && peak_kb >= 0 && decoded.ok) ? (peak_kb * 1024 - b) : -1;
        const ssize_t written = write(cal_pipe[1], &delta, sizeof(delta));
        (void)written;
        close(cal_pipe[1]);
        _exit(0);
      }
      close(cal_pipe[1]);
      long delta = -1;
      const ssize_t got = read(cal_pipe[0], &delta, sizeof(delta));
      close(cal_pipe[0]);
      int cal_status = 0;
      waitpid(cal_pid, &cal_status, 0);
      if (got == static_cast<ssize_t>(sizeof(delta)) && delta > 0) {
        cal_delta_bytes = delta;
        cal_ok = true;
      }
    }
    check(cal_ok,
          "Group 2 calibration: measured a real, positive peak-usage delta for an unconstrained "
          "decode_image_file(png_pal_12000.png) call");

    if (!cal_ok) {
      std::fprintf(stderr,
                   "Group 2: SKIPPED -- calibration failed (pipe/fork/proc read issue?) -- "
                   "inconclusive, not a failure\n");
    } else {
      const pid_t pid = fork();
      check(pid >= 0, "Group 2: fork() succeeded");

      if (pid == 0) {
        // -------------------------------------------------------------------------------------
        // EN: STAGE 2/2 -- SQUEEZE. baseline + cal_delta_bytes - margin, margin = 1/10 of the
        //     CALIBRATED delta -- NOT the 1/4 image_decode_hardening_sanity.cpp's own Group B
        //     uses for ITS (much smaller, 2560x2048/20 MiB) hand-rolled fixture. Measured, on
        //     THIS 12000x12000/~1099 MiB fixture, BEFORE this margin was picked (a throwaway
        //     bisection probe, DEC-NOTHROW's own try/catch removed in an isolated
        //     `tools/mutation_sandbox.sh` sandbox, never the tracked file): margin fractions
        //     0.05-0.20 reliably land the forced failure INSIDE the C++ `assign()` this
        //     library's own `decode_straight_rgba()` performs (throws `std::bad_alloc` --
        //     exactly what DEC-NOTHROW's `try`/`catch` exists to catch); 0.25 and above
        //     reliably land it INSIDE `stb_image`'s own plain `malloc()` instead (returns
        //     `NULL`, `decode_straight_rgba()` reports `ok == false` with NO exception at all --
        //     an ALREADY-safe path, unaffected by whether DEC-NOTHROW's guard exists). 0.25 is
        //     exactly the fraction that DOES generalise from the smaller fixture; it does NOT
        //     here -- confirmed both ways: with the guard present, 0.10/0.18/0.22 all exited
        //     cleanly with `ok == false` (3 repeats each, zero variance); with the guard
        //     removed, the SAME three fractions all `SIGABRT`ed (3 repeats each, zero
        //     variance). 0.10 is the fraction actually wired in below -- comfortably inside the
        //     confirmed-crashing range, with headroom on BOTH sides of the measured 0.20-0.25
        //     transition (unlike image_decode_hardening_sanity.cpp's own Group B, whose
        //     smaller-margin attempt, 1/16, occasionally let the constrained run "unexpectedly
        //     fit" -- the OPPOSITE failure mode from squeezing too tight -- this fixture's own
        //     bisection showed no such variance even at 0.05, but 0.10 is used rather than 0.05
        //     for the same margin-of-safety reasoning, not because 0.05 itself was observed to
        //     be unstable). The absolute-byte overhead a squeeze margin has to clear (malloc
        //     arena bookkeeping, page rounding, ASLR guard regions) is roughly CONSTANT
        //     regardless of decode size, so it is a much SMALLER fraction of a ~1099 MiB delta
        //     than of a ~20 MiB one -- which is why the two files' own margins differ by a
        //     factor of 2.5x rather than being copy-pasted, and why this file reimplements the
        //     oracle independently instead of sharing a constant with that one (see this file's
        //     own top comment for the disjoint-files-in-the-same-wave reasoning too).
        // PT: ESTÁGIO 2/2 -- APERTAR. baseline + cal_delta_bytes - margem, margem = 1/10 do
        //     delta CALIBRADO -- NÃO o 1/4 que o próprio Grupo B de image_decode_hardening_
        //     sanity.cpp usa pra fixture DELE (bem menor, 2560x2048/20 MiB, feita à mão).
        //     Medido, nesta fixture 12000x12000/~1099 MiB, ANTES desta margem ser escolhida
        //     (uma sonda de bisecção descartável, com o try/catch do DEC-NOTHROW removido num
        //     sandbox isolado do `tools/mutation_sandbox.sh`, nunca no arquivo rastreado):
        //     frações de margem 0.05-0.20 pousam a falha forçada de forma confiável DENTRO do
        //     `assign()` C++ que o próprio `decode_straight_rgba()` desta biblioteca faz (lança
        //     `std::bad_alloc` -- exatamente o que o `try`/`catch` do DEC-NOTHROW existe pra
        //     pegar); 0.25 pra cima pousa de forma confiável DENTRO do `malloc()` puro do
        //     próprio `stb_image` (devolve `NULL`, `decode_straight_rgba()` reporta
        //     `ok == false` SEM exceção nenhuma -- um caminho JÁ seguro, não afetado por a
        //     guarda do DEC-NOTHROW existir ou não). 0.25 é exatamente a fração que GENERALIZA
        //     da fixture menor; AQUI não generaliza -- confirmado dos dois lados: com a guarda
        //     presente, 0.10/0.18/0.22 saíram todas limpas com `ok == false` (3 repetições
        //     cada, variância zero); com a guarda removida, as MESMAS três frações deram
        //     `SIGABRT` todas (3 repetições cada, variância zero). 0.10 é a fração de fato
        //     conectada abaixo -- confortavelmente dentro da faixa confirmada-que-crasha, com
        //     folga dos DOIS lados da transição medida 0.20-0.25 (diferente do próprio Grupo B
        //     de image_decode_hardening_sanity.cpp, cuja tentativa de margem menor, 1/16,
        //     ocasionalmente deixava a execução restringida "caber inesperadamente" -- o modo
        //     de falha OPOSTO de apertar demais -- a bisecção desta fixture não mostrou
        //     variância nenhuma nem em 0.05, mas 0.10 é usado em vez de 0.05 pelo mesmo
        //     racional de margem-de-segurança, não porque 0.05 em si tenha sido observado
        //     instável). O overhead em bytes absolutos que uma margem de aperto precisa
        //     superar (contabilidade de arena do malloc, arredondamento de página, regiões de
        //     guarda ASLR) é aproximadamente CONSTANTE independente do tamanho do decode,
        //     então é uma fração bem MENOR de um delta de ~1099 MiB do que de um de ~20 MiB --
        //     por isso as margens dos dois arquivos diferem por um fator de 2,5x em vez de
        //     serem copiadas-e-coladas, e por isso este arquivo reimplementa o oráculo de
        //     forma independente em vez de compartilhar uma constante com aquele (ver o
        //     próprio comentário de topo deste arquivo pro racional de arquivos-disjuntos-na-
        //     mesma-onda também).
        // -------------------------------------------------------------------------------------
        const long baseline = read_vm_size_bytes();
        if (baseline < 0)
          _exit(2); // EN: cannot measure -- inconclusive. PT: não dá pra medir -- inconclusivo.

        const long margin = cal_delta_bytes / 10;
        const rlim_t limit = static_cast<rlim_t>(baseline) + static_cast<rlim_t>(cal_delta_bytes - margin);
        struct rlimit rl;
        rl.rlim_cur = limit;
        rl.rlim_max = limit;
        if (setrlimit(RLIMIT_AS, &rl) != 0)
          _exit(3); // EN: could not clamp -- inconclusive. PT: não deu pra apertar -- inconclusivo.

        // EN: THE call under test -- decode_image_file() end-to-end, on the consumer's OWN
        //     bytes. If DEC-NOTHROW regresses, std::bad_alloc propagates out of main()
        //     uncaught -> std::terminate() -> abort() -> SIGABRT, caught by the parent's
        //     WIFSIGNALED() check below.
        // PT: A chamada sob teste -- decode_image_file() ponta-a-ponta, sobre os PRÓPRIOS
        //     bytes do consumidor. Se DEC-NOTHROW regredir, std::bad_alloc se propaga pra fora
        //     do main() não-capturada -> std::terminate() -> abort() -> SIGABRT, pego pela
        //     checagem WIFSIGNALED() do pai abaixo.
        const DecodedImagePixels decoded = decode_image_file(path.c_str());
        _exit(decoded.ok ? 0 : 1); // 0 = unexpectedly fit; 1 = ok==false as expected under the squeeze.
      }

      int status = 0;
      const pid_t waited = waitpid(pid, &status, 0);
      check(waited == pid, "Group 2: waitpid() reaped the forked child");

      const bool signalled = WIFSIGNALED(status);
      char sig_msg[192];
      std::snprintf(sig_msg, sizeof(sig_msg),
                    "Group 2 (DEC-NOTHROW): child decoding png_pal_12000.png was NOT killed by a "
                    "signal (uncaught std::bad_alloc would SIGABRT) -- WIFSIGNALED=%d, signal=%d",
                    signalled ? 1 : 0, signalled ? WTERMSIG(status) : 0);
      check(!signalled, sig_msg);

      if (!signalled && WIFEXITED(status)) {
        const int code = WEXITSTATUS(status);
        if (code == 2) {
          std::fprintf(stderr,
                       "Group 2: SKIPPED oracle body -- child could not read /proc/self/status "
                       "VmSize (non-Linux or unreadable /proc?) -- inconclusive, not a failure\n");
        } else if (code == 3) {
          std::fprintf(stderr,
                       "Group 2: SKIPPED oracle body -- child's setrlimit(RLIMIT_AS) failed "
                       "(sandboxed/restricted environment?) -- inconclusive, not a failure\n");
        } else {
          check(code == 1,
                "Group 2: decode_image_file(png_pal_12000.png) reported ok == false under the "
                "forced squeeze (exit 1 expected; 0 means the allocation unexpectedly fit -- "
                "widen the budget)");
        }
      }
    }
  }

  if (g_failures > 0) {
    std::fprintf(stderr, "image_decode_probe_corpus_sanity: %d assertion(s) FAILED\n", g_failures);
    return 1;
  }
  std::puts("image_decode_probe_corpus_sanity: PASS");
  return 0;
}
